func preorderTraversal(_ root: TreeNode?) -> [Int] {
    var result = [Int]()
    guard let root = root else { return result }
    var stack = [root]
    while !stack.isEmpty {
        let current = stack.removeLast()
        // 先右后左，这样出栈的时候才是左右顺序
        if let node = current.right { // 右
            stack.append(node)
        }
        if let node = current.left { // 左
            stack.append(node)
        }
        result.append(current.val) // 中
    }
    return result
}

