    var current: TreeNode! = root
    while current != nil || !stack.isEmpty {
        if current != nil { // 先访问到最左叶子
            stack.append(current)
            current = current.left // 左
        } else {
            current = stack.removeLast()
            result.append(current.val) // 中
            current = current.right // 右
        }
    }
    return result
}
