public:
    int countNodes(TreeNode* root) {
        queue<TreeNode*> que;
        if (root != NULL) que.push(root);
        int result = 0;
        while (!que.empty()) {
            int size = que.size();
            for (int i = 0; i < size; i++) {
                TreeNode* node = que.front();
                que.pop();
                result++;   // 记录节点数量
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
        }
        return result;
    }
};
 12345678910111213141516171819时间复杂度：O(n) 空间复杂度：O(n)  完全二叉树 以上方法都是按照普通二叉树来做的，对于完全二叉树特性不了解的同学可以看这篇 关于二叉树，你该了解这些！，这篇详细介绍了各种二叉树的特性。 在完全二叉树中，除了最底层节点可能没填满外，其余每层节点数都达到最大值，并且最下面一层的节点都集中在该层最左边的若干位置。若最底层为第 h 层，则该层包含 1~ 2^(h-1)  个节点。 大家要自己看完全二叉树的定义，很多同学对完全二叉树其实不是真正的懂了。 我来举一个典型的例子如题：  完全二叉树只有两种情况，情况一：就是满二叉树，情况二：最后一层叶子节点没有满。 对于情况一，可以直接用 2^树深度 - 1 来计算，注意这里根节点深度为1。 对于情况二，分别递归左孩子，和右孩子，递归到某一深度一定会有左孩子或者右孩子为满二叉树，然后依然可以按照情况1来计算。 完全二叉树（一）如图：
