    if root.left ==  nil && root.right == nil {
        var str = ""
        for i in 0 ..< path.count - 1 {
            str.append("\(path[i])->")
        }
        str.append("\(path.last!)")
        res.append(str)
        return
    }
    if let left = root.left {
        _binaryTreePaths(left, path: &path, res: &res)
        path.removeLast()
    }
    if let right = root.right {
        _binaryTreePaths(right, path: &path, res: &res)
        path.removeLast()
    }
